(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB____1LC1RD_0RA0LC_1RB___ : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB____1LC1RD_0RA0LC_1RB___ /\
  lift (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB____1LC1RD_0RA0LC_1RB___) = lift (Cc (Pos.succ p)).
Proof.
