  unfold Cc_1RB____1LC1RD_0RA0LC_1RB___, cden, P0_1RB____1LC1RD_0RA0LC_1RB___, P1_1RB____1LC1RD_0RA0LC_1RB___; cbn [c_st c_l c_h c_r].
