(** ** The lap *)

Lemma lap_1RB____1LC1RD_0RA0LC_1RB___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
