  - destruct (lapi_1RB____1LC1RD_0RA0LC_1RB___ p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB____1LC1RD_0RA0LC_1RB___ B0_1RB____1LC1RD_0RA0LC_1RB___ B1_1RB____1LC1RD_0RA0LC_1RB___ 4 8 p j' [] []).
    + exact run_ovf_1RB____1LC1RD_0RA0LC_1RB___.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB____1LC1RD_0RA0LC_1RB___ p j' E).
    + exact (geo_1RB____1LC1RD_0RA0LC_1RB___ p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB____1LC1RD_0RA0LC_1RB___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

