  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB____1LC1RD_0RA0LC_1RB___ p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB____1LC1RD_0RA0LC_1RB___ p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB____1LC1RD_0RA0LC_1RB___ : forall t, ~ In t pins_1RB____1LC1RD_0RA0LC_1RB___ ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
