(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB____1LC1RD_0RB0LC_1LB1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_1RB____1LC1RD_0RB0LC_1LB1RA /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_1RB____1LC1RD_0RB0LC_1LB1RA = Cc (Pos.succ p).
