(** ** The lap *)

Lemma lap_1RB____1LC____1RD0LC_0RD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
