    apply (lap_of_run tm Cc true true cho_1RB____1LC____1RD0LC_0RD0LA B0_1RB____1LC____1RD0LC_0RD0LA B1_1RB____1LC____1RD0LC_0RD0LA 2 8 p j' [] []).
    + exact run_ovf_1RB____1LC____1RD0LC_0RD0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB____1LC____1RD0LC_0RD0LA p j' E).
    + exact (geo_1RB____1LC____1RD0LC_0RD0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB____1LC____1RD0LC_0RD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
