  apply (fire_of_run_instr tm Cc true true l B0_1RB____1LC____1RD0LC_0RD0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB____1LC____1RD0LC_0RD0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
