  lift (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB____1RC1RB_1LC1LD_0RA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (DpCounter.cview_some_D p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB____1RC1RB_1LC1LD_0RA0LD, cden, Z0_1RB____1RC1RB_1LC1LD_0RA0LD, Z1_1RB____1RC1RB_1LC1LD_0RA0LD; cbn [c_st c_l c_h c_r].
