    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC1RB_1LC1LD_0RA0LD [SWin 2; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
