Module LAPT_1RB____1RC____1LD1RB_0RA0LD.
(** * LAPT_1RB____1RC____1LD1RB_0RA0LD: TRANSITION-LEVEL board for machine 1RB---_1RC---_1LD1RB_0RA0LD, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Bp digit alphabet (BpCounter.v), anchored at

      Cc p = (StA, (Bp p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  4*j+6 steps
      overflow  (cview p = (S j, None)):   4*j+10 steps

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 198 anchors.
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter BpCounter LapCertGlue LapCertGlueLift.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_1RB____1RC____1LD1RB_0RA0LD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB____1RC____1LD1RB_0RA0LD.

(** 1RB---_1RC---_1LD1RB_0RA0LD *)
(** 1RB---_1RC---_1LD1RB_0RA0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB____1RC____1LD1RB_0RA0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => None
  | StB, S0 => mk S1 DR StC | StB, S1 => None
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB---_1LC---_1RD1LB_0LA0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB____1RC____1LD1RB_0RA0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => None
  | StB, S0 => mk S1 DL StC | StB, S1 => None
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB____1RC____1LD1RB_0RA0LD : list Instr := [(StA, S1); (StB, S1)].
Definition tmw_1RB____1RC____1LD1RB_0RA0LD : TM := tm_wrap_trs tmm_1RB____1RC____1LD1RB_0RA0LD pins_1RB____1RC____1LD1RB_0RA0LD.
Local Notation tm := tmw_1RB____1RC____1LD1RB_0RA0LD.

Lemma mirror_ok_1RB____1RC____1LD1RB_0RA0LD : mirror_tm tm_1RB____1RC____1LD1RB_0RA0LD = tmm_1RB____1RC____1LD1RB_0RA0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB____1RC____1LD1RB_0RA0LD (p : positive) : cconf := (StA, (Bp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB____1RC____1LD1RB_0RA0LD.

(** ** The certificate *)

Definition A0_1RB____1RC____1LD1RB_0RA0LD : sconf := mkC StA (mkS [] [S0;S1] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB____1RC____1LD1RB_0RA0LD : sconf := mkC StA (mkS [] [S0;S0] 1 0 [S0;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB____1RC____1LD1RB_0RA0LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SWinR 2; SUnrotL 1].

Lemma run_int_1RB____1RC____1LD1RB_0RA0LD : srun tm false true chi_1RB____1RC____1LD1RB_0RA0LD A0_1RB____1RC____1LD1RB_0RA0LD = Some (A1_1RB____1RC____1LD1RB_0RA0LD, 4, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB____1RC____1LD1RB_0RA0LD : sconf := mkC StA (mkS [S0;S1] [S0;S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB____1RC____1LD1RB_0RA0LD : sconf := mkC StA (mkS [] [S0;S0] 1 1 [S0;S1]) S0 (mkS [S0] [] 0 0 []).
Definition cho_1RB____1RC____1LD1RB_0RA0LD : list lstep := [SWin 2; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 2; SWinR 2; SFoldL 1].

Lemma run_ovf_1RB____1RC____1LD1RB_0RA0LD : srun tm true true cho_1RB____1RC____1LD1RB_0RA0LD B0_1RB____1RC____1LD1RB_0RA0LD = Some (B1_1RB____1RC____1LD1RB_0RA0LD, 4, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB____1RC____1LD1RB_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB____1RC____1LD1RB_0RA0LD.
Proof.
  intros p j q0 E. destruct (BpCounter.cview_some_B p j q0 E) as (H1 & _).
  unfold Cc_1RB____1RC____1LD1RB_0RA0LD, cden, A0_1RB____1RC____1LD1RB_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB____1RC____1LD1RB_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Bp q0 ++ [S0]) [] j A1_1RB____1RC____1LD1RB_0RA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (BpCounter.cview_some_B p j q0 E) as (_ & H2).
  unfold Cc_1RB____1RC____1LD1RB_0RA0LD, cden, A1_1RB____1RC____1LD1RB_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB____1RC____1LD1RB_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 6), (cden (Bp q0 ++ [S0]) [] j A1_1RB____1RC____1LD1RB_0RA0LD).
  split; [lia|]. split; [| exact (gei_1RB____1RC____1LD1RB_0RA0LD p j q0 E)].
  rewrite (gsi_1RB____1RC____1LD1RB_0RA0LD p j q0 E).
  exact (srun_sound tm false true chi_1RB____1RC____1LD1RB_0RA0LD A0_1RB____1RC____1LD1RB_0RA0LD A1_1RB____1RC____1LD1RB_0RA0LD 4 6
           run_int_1RB____1RC____1LD1RB_0RA0LD (Bp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB____1RC____1LD1RB_0RA0LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB____1RC____1LD1RB_0RA0LD.
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (H1 & _).
  unfold Cc_1RB____1RC____1LD1RB_0RA0LD, cden, B0_1RB____1RC____1LD1RB_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB____1RC____1LD1RB_0RA0LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB____1RC____1LD1RB_0RA0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB____1RC____1LD1RB_0RA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB____1RC____1LD1RB_0RA0LD
             = (StA, (rep [S0;S0] (S j) ++ [S0;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB____1RC____1LD1RB_0RA0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB____1RC____1LD1RB_0RA0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB____1RC____1LD1RB_0RA0LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB____1RC____1LD1RB_0RA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB____1RC____1LD1RB_0RA0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB____1RC____1LD1RB_0RA0LD B0_1RB____1RC____1LD1RB_0RA0LD B1_1RB____1RC____1LD1RB_0RA0LD 4 10 p j' [] []).
    + exact run_ovf_1RB____1RC____1LD1RB_0RA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB____1RC____1LD1RB_0RA0LD p j' E).
    + exact (geo_1RB____1RC____1LD1RB_0RA0LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB____1RC____1LD1RB_0RA0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB____1RC____1LD1RB_0RA0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB____1RC____1LD1RB_0RA0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB____1RC____1LD1RB_0RA0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB____1RC____1LD1RB_0RA0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB____1RC____1LD1RB_0RA0LD : forall t, ~ In t pins_1RB____1RC____1LD1RB_0RA0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB____1RC____1LD1RB_0RA0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [SWin 2; SCycL 2 0; SWin 1; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [SWin 2; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB____1RC____1LD1RB_0RA0LD [SWin 2; SCycL 2 0; SWin 1; SWinL 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB____1RC____1LD1RB_0RA0LD : NeverQuasiHaltsTr tmm_1RB____1RC____1LD1RB_0RA0LD.
Proof.
  apply (glue_neverqhtr tmm_1RB____1RC____1LD1RB_0RA0LD pins_1RB____1RC____1LD1RB_0RA0LD Cc 1).
  - exact boot_1RB____1RC____1LD1RB_0RA0LD.
  - intros p _. apply lap_1RB____1RC____1LD1RB_0RA0LD.
  - intros t Ht p _. apply fire_1RB____1RC____1LD1RB_0RA0LD. exact Ht.
Qed.

Theorem nqhtr_1RB____1RC____1LD1RB_0RA0LD : NeverQuasiHaltsTr tm_1RB____1RC____1LD1RB_0RA0LD.
Proof. apply (neverqhtr_mirror tm_1RB____1RC____1LD1RB_0RA0LD). rewrite mirror_ok_1RB____1RC____1LD1RB_0RA0LD. exact nqhtrm_1RB____1RC____1LD1RB_0RA0LD. Qed.

Theorem nonhalt_1RB____1RC____1LD1RB_0RA0LD : NonHalt tm_1RB____1RC____1LD1RB_0RA0LD.
